// src/components/SiteHeader.jsx
import React, { useEffect, useState } from 'react';
import SearchBarUnified from './SearchBarUnified';
import { getAudience, setAudience } from '../utils/audience';

export default function SiteHeader(){
  const [scrolled, setScrolled] = useState(false);
  const [aud, setAud] = useState(getAudience() || 'RESIDENT');

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 10);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const switchAud = (v) => {
    setAudience(v);
    setAud(v);
    // no recargo; el header se actualiza y el backend ya recibe el header X-Audience
  };

  return (
    <>
      {/* HERO inicial (logo centrado arriba del buscador) */}
      <div className={`cp-hero ${scrolled ? 'is-hidden' : ''}`}>
        <div className="cp-hero-inner">
          <a className="cp-brand-big" href="/">
            <img src="/logo.png" alt="Conecta Pinamar" />
          </a>
          <div className="cp-hero-search">
            <SearchBarUnified />
          </div>
        </div>
      </div>

      {/* HEADER sticky que aparece al scrollear */}
      <div className={`cp-header ${scrolled ? 'show' : ''}`}>
        <div className="cp-header-inner">
          <a className="cp-brand" href="/">
            <img src="/logo.png" alt="Conecta Pinamar" />
          </a>

          <div className="cp-search-outer">
            <SearchBarUnified />
          </div>

          <div className="cp-right">
            <a className="cp-btn" href="#">MIS CUPONES</a>

            <div className="cp-aud">
              <button className="cp-aud-pill" aria-haspopup="menu" aria-expanded="false">
                {aud === 'TOURIST' ? 'Turista' : 'Residente'}
              </button>
              <div className="cp-aud-menu" role="menu">
                <button onClick={() => switchAud('RESIDENT')}>Residente</button>
                <button onClick={() => switchAud('TOURIST')}>Turista</button>
              </div>
            </div>

            <button className="cp-burger" aria-label="Menú">
              <span></span><span></span><span></span>
            </button>
          </div>
        </div>
      </div>
    </>
  );
}
